-- rollback: ALTER TABLE public.studios DROP COLUMN IF EXISTS onboarded_at;
--           DROP INDEX IF EXISTS idx_studios_onboarded_at;

-- Adds onboarded_at so Step 4 can stamp the completion moment.
-- Drives downstream email triggers, funnel analytics, and the dashboard
-- "first-visit" state for the deferred logo card.
alter table public.studios
  add column if not exists onboarded_at timestamptz;

create index if not exists idx_studios_onboarded_at
  on public.studios (onboarded_at)
  where onboarded_at is not null;

